  updatedAt: string | undefined;
  identities: Identity[];
  metadata: string | undefined;
}
```

#### `Identity` type (from `src/types/auth.ts`)

```ts
type Identity = {
  connectionId: string;
  organizationId: string;
  connectionType: string;
  providerName: string;
  social: boolean;
  providerRawAttributes: string;
}
```

#### `TokenResponse` type (internal, from `src/types/auth.ts`)

```ts
type TokenResponse = {
  access_token: string;
  id_token: string;
  expires_in: number;
}
```

Note: `TokenResponse` is the raw API response. The SDK transforms it into `AuthenticationResponse` (with camelCase field names and a parsed `User` object).

#### Other exported types

```ts
