      <html>
      <head><title>Dashboard</title></head>
      <body>
        <h1>Dashboard</h1>
        <p>Email: ${email}</p>
        <p>Organization ID: ${oid}</p>
        <a href="/logout">Sign out</a>
      </body>
      </html>
    `);
  } catch (err) {
    console.error('Token decode error:', err);
    res.redirect('/login');
  }
});

